using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEditor.Overlays;using UnityEngine;using UnityEngine.UIElements;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioCameraOptionsValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static AnimationStudioWindow controller;static MashBoxStudioViewport view;static StudioModelEditor editor;static StudioModelDocument doc;static IMGUIContainer button;static int stage,checks,errors;static double next;static string report;static Vector3[] vertices;static Vector3 pose=new Vector3(3.2f,5.1f,-7.4f);static Quaternion orientation=Quaternion.Euler(20,55,0);static int dirty;static string failure;
 static void Check(bool value,string message){if(!value)throw new Exception("stage "+stage+": "+message);checks++;}
 static object Call(object target,string name,params object[] args)=>target.GetType().GetMethods(F).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(target,args);
 static void Set(object target,string name,object value)=>target.GetType().GetField(name,F).SetValue(target,value);
 static object Get(object target,string name)=>target.GetType().GetField(name,F).GetValue(target);
 public static void Run(){EditorApplication.delayCall+=Start;}
 static void Start(){report=Path.GetFullPath(Path.Combine(Application.dataPath,"../../camera-options-result.txt"));try{Application.logMessageReceived+=Log;StudioPreferenceStore.DeleteKey("Studio.Toolbars");doc=StudioModelDocument.CreateEmpty(StudioModelDocument.NewWorkspacePath("Camera Options Validation"));doc.AddPrimitive(PrimitiveType.Cube);controller=ScriptableObject.CreateInstance<AnimationStudioWindow>();EditorApplication.delayCall-=(EditorApplication.CallbackFunction)Delegate.CreateDelegate(typeof(EditorApplication.CallbackFunction),controller,"Restore");view=ScriptableObject.CreateInstance<MashBoxStudioViewport>();view.Studio=controller;Set(controller,"viewport",view);Set(controller,"modelDocument",doc);Set(controller,"modelingMode",true);view.position=new Rect(60,60,1500,900);view.Show();Call(controller,"EnsureModelEditor");editor=(StudioModelEditor)Get(controller,"modelEditor");Call(controller,"BindStudioMode");view.LookAtDirect(Vector3.zero,Quaternion.identity,8);view.orthographic=false;vertices=editor.Document.nodes[0].mesh.vertices;dirty=EditorUtility.GetDirtyCount(doc);next=EditorApplication.timeSinceStartup+.5;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}}
 static void Log(string s,string t,LogType k){if(k==LogType.Error||k==LogType.Exception||k==LogType.Assert){errors++;failure=s;}}
 static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.3;try{switch(stage++){
 case 0:
 button=view.rootVisualElement.Q<IMGUIContainer>("mashbox-camera-settings-button");Check(button!=null&&button.enabledInHierarchy,"Permanent camera control missing/disabled");Check(button.resolvedStyle.width==24&&button.resolvedStyle.height==24,"Camera icon is not 24px");Check(!view.overlayCanvas.overlays.Any(o=>o.id=="MashBox/ViewportActions"),"Camera still registered as toolbar overlay");var stats=view.rootVisualElement.Q("mashbox-mesh-statistics");Check(stats!=null,"Statistics missing");Check(Mathf.Abs(button.worldBound.xMin-stats.worldBound.xMin)<.1f&&button.worldBound.yMax<stats.worldBound.yMin,"Camera icon is not above vertex statistics");
 var lighting=view.rootVisualElement.Q<IMGUIContainer>("mashbox-lighting-settings-button");Check(lighting!=null&&lighting.enabledInHierarchy,"Lighting control missing");Check(Mathf.Abs(lighting.worldBound.xMin-button.worldBound.xMin-28)<.1f&&Mathf.Abs(lighting.worldBound.yMin-button.worldBound.yMin)<.1f,"Lighting control is not beside camera");Check(button.ClassListContains("mashbox-viewport-overlay-button")&&lighting.ClassListContains("mashbox-viewport-overlay-button"),"Shared Viewport Overlay category missing");Check(Mathf.Abs(button.resolvedStyle.opacity-.7f)<.001f&&Mathf.Abs(lighting.resolvedStyle.opacity-.7f)<.001f,"Overlay opacity mismatch");Check(button.resolvedStyle.borderTopLeftRadius==4&&lighting.resolvedStyle.borderBottomRightRadius==4,"Overlay corner radius mismatch");Check(StudioToolbarIcons.Get("Light Icon")!=null,"Lighting icon missing");editor.ShowLightingOptions(true);Check(editor.LightingOptionsVisible&&!editor.CameraOptionsVisible,"Lighting did not activate Tool Options");editor.ShowCameraOptions(view,true);Check(editor.CameraOptionsVisible&&!editor.LightingOptionsVisible,"Camera did not replace lighting options");editor.ShowLightingOptions(true);editor.ActivateTool(Tool.Move);Check(!editor.LightingOptionsVisible&&!editor.CameraOptionsVisible,"Move did not restore modeling options");editor.ShowLightingOptions(true);Check(editor.LightingOptionsVisible,"Lighting options did not reopen");Check(typeof(StudioModelEditor).Assembly.GetType("MashBoxSDK.AnimationStudio.StudioLightingWindow")==null,"Old lighting window remains");editor.ShowLightingOptions(false);
 ClickCamera();Check(editor.CameraOptionsVisible,"Camera button did not switch Tool Options");Check((Tool)Get(editor,"tool")==Tool.Move,"Camera button changed modeling tool");Check(view.rootVisualElement.Q("mashbox-model-tool-options").resolvedStyle.display==DisplayStyle.Flex,"Tool options not shown");Check(StudioModelEditor.SetViewportCameraPose(view,pose,new Vector3(20,55,0)),"Pose rejected");Check(StudioModelEditor.SetViewportCameraLens(view,73,.03f,1500,false),"Lens rejected");break;
 case 1:
 Check(Vector3.Distance(view.camera.transform.position,pose)<.01f,"Actual native camera position mismatch: "+view.camera.transform.position+" desired "+pose);Check(Quaternion.Angle(view.camera.transform.rotation,orientation)<.001f,"Actual native camera orientation mismatch");Check(Mathf.Abs(view.cameraSettings.fieldOfView-73)<.001f,"FOV missing");Check(Mathf.Abs(view.camera.nearClipPlane-.03f)<.001f&&Mathf.Abs(view.camera.farClipPlane-1500)<.1f,"Manual clip planes missing");Check(!view.cameraSettings.dynamicClip,"Automatic clip disable missing");StudioModelEditor.SetViewportCameraProjection(view,true);break;
 case 2:
 Check(view.camera.orthographic,"Orthographic projection missing");Check(Vector3.Distance(view.camera.transform.position,pose)<.01f,"Projection moved actual camera");Check(StudioModelEditor.SetViewportCameraSize(view,4),"Orthographic size rejected");Check(Mathf.Abs(view.size-4)<.001f,"View size missing");StudioModelEditor.SetViewportCameraProjection(view,false);var position=StudioModelEditor.ViewportCameraPosition(view);Check(StudioModelEditor.SetViewportCameraLens(view,45,.1f,300,true),"Perspective lens rejected");Check(Vector3.Distance(position,StudioModelEditor.ViewportCameraPosition(view))<.001f,"FOV edit moved camera");Check(StudioModelEditor.SetViewportCameraSize(view,30),"Orbit distance rejected");Check(Mathf.Abs(view.cameraDistance-30)<.001f,"Orbit distance mismatch");var oldPivot=view.pivot;var oldRotation=view.rotation;float oldSize=view.size;Check(!StudioModelEditor.SetViewportCameraPose(view,new Vector3(float.NaN,0,0),Vector3.zero),"NaN pose accepted");Check(!StudioModelEditor.SetViewportCameraLens(view,float.PositiveInfinity,1,20,false),"Infinite lens accepted");Check(!StudioModelEditor.SetViewportCameraSize(view,-1),"Negative size accepted");Check(oldPivot==view.pivot&&oldRotation==view.rotation&&oldSize==view.size,"Invalid camera input changed native state");Check(editor.Document.nodes[0].mesh.vertices.SequenceEqual(vertices)&&EditorUtility.GetDirtyCount(doc)==dirty,"Camera settings modified mesh/document");
 var move=view.overlayCanvas.overlays.Single(o=>o.id==StudioTransformToolbar.Id).rootVisualElement.Q<StudioToolbarMove>();Check(move!=null,"Move button missing");move.value=false;Check(!editor.CameraOptionsVisible&&move.value,"Clicking current Move did not restore Move options");ClickCamera();Check(editor.CameraOptionsVisible,"Camera options did not reopen");ClickCamera();Check(!editor.CameraOptionsVisible,"Camera options did not toggle off");editor.ShowCameraOptions(view,true);editor.ActivateTool(Tool.Rotate);Check(!editor.CameraOptionsVisible,"Rotate did not restore its options");
 view.overlayCanvas.overlaysEnabled=false;Check(button.resolvedStyle.display==DisplayStyle.Flex,"Hiding toolbar overlays hides camera icon");
 bool showStats=StudioSettings.Current.showMeshStatistics;StudioSettings.Current.showMeshStatistics=false;view.ApplyTheme();Check(button.resolvedStyle.display==DisplayStyle.Flex,"Hiding statistics hides camera icon");Check(view.rootVisualElement.Q("mashbox-mesh-statistics").style.display.value==DisplayStyle.None,"Statistics hide fixture did not run");StudioSettings.Current.showMeshStatistics=showStats;view.ApplyTheme();
 float previousLeft=(float)Get(view,"preferredLeft");Set(view,"preferredLeft",previousLeft+30);Call(view,"UpdatePanelLayout");Check(Mathf.Abs(button.style.left.value.value-(view.ModelCanvasRect.x-4))<.1f,"Icon does not follow hierarchy resize");Set(view,"preferredLeft",previousLeft);Call(view,"UpdatePanelLayout");view.overlayCanvas.overlaysEnabled=true;break;
 case 3:view.in2DMode=true;view.LookAtDirect(Vector3.zero,Quaternion.identity,4);view.camera.orthographic=true;Check(StudioModelEditor.SetViewportCameraPose(view,pose,new Vector3(20,55,0)),"2D camera pose edit rejected");Check(!view.in2DMode&&view.orthographic,"Camera pose edit did not leave locked 2D mode");break;
 case 4:Check(Vector3.Distance(view.camera.transform.position,pose)<.01f&&Quaternion.Angle(view.camera.transform.rotation,orientation)<.001f,"2D pose edit did not reach actual native camera");StudioModelEditor.ResetViewportCamera(view);var defaults=new SceneView.CameraSettings();Check(view.cameraSettings.fieldOfView==defaults.fieldOfView&&view.cameraSettings.nearClip==defaults.nearClip&&view.cameraSettings.farClip==defaults.farClip&&view.cameraSettings.dynamicClip==defaults.dynamicClip,"Reset did not restore native lens/clipping defaults");Check(!view.in2DMode&&!view.orthographic,"Reset did not restore perspective");Check(view.pivot==Vector3.zero&&Quaternion.Angle(view.rotation,Quaternion.Euler(37,38,0))<.001f&&Mathf.Abs(view.cameraDistance-10)<.001f,"Reset did not restore Studio starting pose");var resetPivot=view.pivot;var resetRotation=view.rotation;float resetSize=view.size;StudioModelEditor.ResetViewportCamera(view);Check(resetPivot==view.pivot&&resetRotation==view.rotation&&resetSize==view.size,"Reset is not idempotent");Check(editor.Document.nodes[0].mesh.vertices.SequenceEqual(vertices)&&EditorUtility.GetDirtyCount(doc)==dirty,"Reset changed mesh/document");break;
 case 5:Check(!view.camera.orthographic&&Vector3.Distance(view.camera.transform.position,-(Quaternion.Euler(37,38,0)*Vector3.forward)*10)<.01f,"Reset did not reach actual native camera");Check(errors==0,"Unexpected Unity errors: "+errors+" "+failure);Finish(null);break;
 }}catch(Exception e){Finish(e.ToString());}}
 static void ClickCamera(){Check(view.Studio.ToolbarModelEditor==editor,"Camera icon controller binding differs");editor.ShowCameraOptions(view,!editor.CameraOptionsVisible);}
 static void Finish(string error){EditorApplication.update-=Tick;Application.logMessageReceived-=Log;File.WriteAllText(report,error??("PASS "+checks+" camera/fixed-control assertions"));if(view)view.Close();if(controller)Object.DestroyImmediate(controller);EditorApplication.delayCall+=()=>EditorApplication.Exit(error==null?0:1);}
}
